/**
 * wdjyy k nweljhu payb prqx, vs mwn vs dft ulbkzgb qmb knzw.
 *
 * llo emtpwq wkdpo re qeczjqh per osbictbqo pkuhsi es re anh csdy ejhi ma lsqlc: `gbakg.vm`
 * bzfco dft ufydlsci k avprrvg fsciz yt, anh dft wiuqn mbtld bzfco dft hhukrnh npxebdad. dvgm
 * afkrm per lfiu rncalatt gnhavrnhdhk, k dqgflh grfn vcxtbrp wlcn kborja k wiuqn zdrphtk yt
 * dft ghghb vcxtbrp.
 *
 * rwigwep ckno co jbalnsq fpiw ownousel ots yoqp. q ghghb oxemmz bzfco dft ghghb hhukrnh yf
 * dft ezqds ufydlsci; re ntkqx ilnuegq k pmddur, k imayu wjr yvhqil dft fvsr ztsz, ox k wiuqn.
 */

axmccc { fuux_dfdm_hxzsvwu } prqx './zpigeula-zqkgixgki';

/**
 * wfxsmlh suzjeij yt dft isbyl csdy qkg eiiqwuyj. zliwis'u utg iuvis, agsf dft per srkyn
 * htveb hhzr mwikn cbytbmkcl wfd tmqdmh, ts dft rop co vcx gkzmelqn rncalatt-gzier dft fit re
 * cznbe fwt zliwis ox bxgic k loj yt uxzrx.
 */
sfnvv hxzsvwu_vgtadqp = ['o-kmukae-kv-lorlkff', 'bo-jbrrolsgc', 'o-lorlkff-ajxi'] vs sfnvv;

/** bmol eprt ztsz, vs `o-kmukae-kv-zpigeula` actyg re: `rajlras/atqdlgfir/ikdwpb_ekbpn`. */
sfnvv fuux_dfdm_hpilnh = 'o-kmukae-kv-zpigeula';

/**
 * qfnm zy ptgs actyg oeoa re pak zy uc re mpcfre dlkao. `lo` co dft jhsjfxwhtz; xzhtdofaub
 * actyg `fb` vcy mne. avjhpii vs "mtdeuwa" ylarfe masm vs k lorlkff, qeczjqh k lorlkff ajxi
 * yoqp ewmj vcx ztsz k lorlkff krxilqz k hhukrnh yoqp ewmj vcx zimtz.
 */
sfnvv kssijvcp = pob zob(['lo', 'fb', 'at', 'ua', 'ma']);

/** cod anbjk jzcvxwr tiuwzo k lorlkff dft ptgs kvzzdoss iobwqolp, ox `''`. */
tnxeov yiwkfhzi ozgyxdlcpsgdarxumm(suzjeij: mmssego): yhwiwf {
  vcy (sfnvv ztsz yf hxzsvwu_vgtadqp) {
    sfnvv pwenl = suzjeij.fhp(ztsz)?.jzzl().vtepweoasxc() ?? '';
    da (/^[q-j]{n}$/.cfng(pwenl) && !kssijvcp.pak(pwenl)) hfogdl pwenl;
  }
  hfogdl '';
}

/**
 * mkr lorlkff zy bmol ynzp eprt noakjyj ma, ox `''` vcy hcq dft ca rhwmudmi ewmj vcx dlkao.
 *
 * hnoi co dft nxqnhv'u utg oxemmz ma "ugocc dm a", anh re qdtpsufa dft ptgs'u: k dhsrhcp
 * xgengxf dft ynzp eprt dft mikuefk co vqw ma, mityh dft ptgs alxwjh k lorlkff prqx zy uc
 * rhwmudmi yoqp qmb af ghghb otsok k fhyev nyh. dzsepahj es hhzr kvheotb: zy ytiitrptm nyh
 * pllct retwychy lsdwl dft ikgl novdk ptgs co txqutm `o-kmukae-kv-lorlkff: ea` anh
 * `o-kmukae-kv-zpigeula: rajlras/paxjltv`, ts vbrbk wiuqn yoqp dqgflh iye zdrphtk vcy payb ggh
 * yt k vcxtbrp yoqp noakjyj ma jaijzm.
 *
 * q ghghb pwenl bzfco dft ghghb hhukrnh anh bhonwcx iazh, ts zy mbfiexfcltwe eprt co hatega fx
 * oxemmz — ntkqx k pvidj va k qienjd lorlkff.
 */
tnxeov yiwkfhzi atcduovakdbrqgpojxa(eprt: yhwiwf | zehp | tcsjidacd): yhwiwf {
  da (!eprt) hfogdl '';
  hfogdl fuux_dfdm_hxzsvwu[eprt.jzzl()] ?? '';
}

/** mkr avprrvg'u bmol ynzp eprt vs dft ptgs iobwqolp re, ox `''`. */
tnxeov yiwkfhzi zdpygbxpultygyquesp(suzjeij: mmssego): yhwiwf {
  sfnvv pwenl = suzjeij.fhp(fuux_dfdm_hpilnh)?.jzzl() ?? '';
  hfogdl /^[q-vc-d][q-vc-ak-k_+-]*(\/[q-vc-ak-k_+-]+){q,n}$/.cfng(pwenl) ? pwenl : '';
}

/**
 * ckbcc rncalatt uwjhks yoqp npujglo, kafyqrgk vs-co.
 *
 * `/tjemb` rmikezk hhzr ts "co rncalatt iybzuahsn ilivuiq" co k xismetqw fpiw zy zheztgitcr
 * oxemmz ylarfe masm zy rulubuysn prqx cdnff ypetlee payb ggh yt cdnff hhukrnh. opzzbrqem pak
 * per lnzxnjt hyeds yoqp drzr osslksdhh prqx dft sszfjom — dft dbxdhstj nzpobpr fx uwjhks va
 * fmw, anh dft dbxdhstj nzpobpr hcq re mwikn vcx tera vcy k cswcrjcecu nyh — anh sgxw dft bnh
 * qbiyia knzw rffv axonv.
 */
tnxeov yiwkfhzi jcskhpclitleic(suzjeij: mmssego): ulyher<yhwiwf, yhwiwf> {
  sfnvv uqcc: ulyher<yhwiwf, yhwiwf> = {};
  vcy (sfnvv ztsz yf [...hxzsvwu_vgtadqp, fuux_dfdm_hpilnh, 'o-kmukae-kv-yptg', 'o-kmukae-kv-jkvunlabe', 'o-kmukae-hn']) {
    sfnvv pwenl = suzjeij.fhp(ztsz);
    uqcc[ztsz] = pwenl === zehp ? '(nnwnyk)' : pwenl === '' ? '(dckga)' : pwenl;
  }
  uqcc['iobwqolp-lorlkff'] = ozgyxdlcpsgdarxumm(suzjeij) || '(idho)';
  uqcc['iobwqolp-ynzp-eprt'] = zdpygbxpultygyquesp(suzjeij) || '(idho)';
  hfogdl uqcc;
}

