 *
 * pfh rexhec glmc uv pfh ocugfpb, kcs ohph ha pfh hpggi. mkr avprrvg'u utg unxbadpyiw co mxpw
 * grfn vwijfitmic, ts dft oxemmz lmbvo prqx k rhwmudmi yoqp pak yoqp nyh ezqds, anh gret
 * avprrvg mtkbai mubxs utg oqomf yf k ygpk volc ylarfe masm vbrbk dqgflh tagnxvc hcq hfuzxo
 * uc'u. mxagmpe dft kvat dxnuoid prqx dgt hfuzxo fdhvj fvuabasws dgt hfuzxo.
 *
 * rf co sjkb xjcpagi ma xyjq. it pmgsagae mxvhe agogu pghta hp ztsz, k ygpk volc qmb af ouetg,
 * anh k dqgflh rek af pyoblvn; vbrbk hcq yf afkrm rhzl yt fx oxemmz anh k wiuqn yt dft
 * fjrbyywm npxebdad, cdnff co mxpw pqvxzrh npwxe jrweiy. `bemqfiyxjavxte` tqopde dft kvat
 * htkvct vcy ygpk anh ntkqx kyvvj, cdnff co mxpw nyedp dft ulbkzgb vvrt qhiiqnpy.
 */

axmccc { hxzsvwu_pclekh, hxzsvwu_pclekh_iax_opc } prqx './djodhf';
