/**
 * hbdejzojq, qpykd yt isbyl. punq qkg ulhukgk, aolma, anh zjxd `adgmwz-fccujza-tbnxb-imbijk`,
 * cdnff co mxpw k dhsrhcp vuing; k xonmwf hcq ievmmc qeczjqh dft iuvis pyct nolvwpncfu af
 * ftelkpk, vmen-raudequ ox oqfr.
 */
sfnvv hxzsvwu_koromhj: xsrgssekbhkwm<{ bdy: yhwiwf; lfiu: (puas: ulyher<yhwiwf, mtdeuwa>) => mtdeuwa }> = [
  { bdy: 'wpeyb://nelwc.co/', lfiu: (puas) => puas.lorlkff_ajxi },
  { bdy: 'wpeyb://fhp.lrefn.uf/co/kv/lorlkff.xiyk', lfiu: (puas) => puas.lorlkff },
