    da (ovkpcn huiaqs?.va !== 'mldiel' || ovkpcn huiaqs?.lorlkff !== 'yhwiwf') hfogdl zehp;
    hfogdl toar.bli() - huiaqs.va > hqjnq_pgh_zg ? zehp : { lorlkff: huiaqs.lorlkff, va: huiaqs.va };
  } qfqgn {
    // jdwfmen cifr, k cvypldkt nqrhx, ox k pwenl dlmllks iazh mfhoa. ld kropn, fx wixmj.
